// Accepts JSON or form-encoded posts from any web form and maps the usual
// field-name variants onto the exact column names used in the sheet.

// ---------- ADD YOUR OWN FIELD NAMES HERE ----------
const ALIASES = {
  full_name: ['name', 'full_name', 'fullname', 'your-name', 'contact_name', 'first_name'],
  phone: ['phone', 'telephone', 'tel', 'phone_number', 'phonenumber', 'mobile', 'your-phone'],
  email: ['email', 'e-mail', 'email_address', 'your-email'],
  message: ['message', 'comments', 'details', 'description', 'job_description', 'your-message'],
  source: ['source', 'utm_source', 'form_name', 'page'],
};
// ---------------------------------------------------

function pick(body, aliases) {
  const keys = Object.keys(body);
  for (const alias of aliases) {
    const match = keys.find((k) => k.toLowerCase() === alias);
    if (match && String(body[match]).trim() !== '') return String(body[match]).trim();
  }
  return '';
}

return $input.all().map((item) => {
  const body = item.json.body || item.json || {};

  const phone = pick(body, ALIASES.phone);
  const email = pick(body, ALIASES.email);

  // Digits only, with a leading US country code dropped, so the same person
  // typing their number two different ways still counts as one lead.
  const digits = phone.replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');

  // Prefixed so the key is never a bare number: a digits-only value gets stored
  // as a number by the spreadsheet and the lookup then stops matching.
  const dedupe_key = digits ? `p:${digits}` : (email ? `e:${email.toLowerCase()}` : '');

  const now = new Date().toISOString();

  // The keys below match the sheet headers exactly, which lets the Google Sheets
  // nodes map them automatically with no manual column mapping.
  return {
    json: {
      received_at: now,
      last_enquiry_at: now,
      full_name: pick(body, ALIASES.full_name),
      phone,
      dedupe_key,
      email,
      message: pick(body, ALIASES.message),
      source: pick(body, ALIASES.source) || 'website',
      enquiry_count: 1,
    },
  };
});

// Builds only the columns that change on a repeat enquiry. Anything not listed
// here keeps its original value in the sheet.
const lead = $('Map Lead Fields').first().json;
const existing = $input.first().json;

return [
  {
    json: {
      dedupe_key: lead.dedupe_key,
      last_enquiry_at: lead.last_enquiry_at,
      message: lead.message,
      source: lead.source,
      enquiry_count: Number(existing.enquiry_count || 1) + 1,
    },
  },
];

// The lookup node replaces the item with an empty object when no match is found,
// so pull the normalised lead back in before the row is written.
return [{ json: $('Map Lead Fields').first().json }];

